// WebhookReceiverInterface represents handlers for receiving inbound
// webhook requests. Each webhook becomes a Handle*Webhook
// method that the implementation fills in. The caller mounts the per-
// webhook echo.HandlerFunc returned by {Op}WebhookHandler at
// whatever URL path they advertise to senders.
type WebhookReceiverInterface interface {
	// The alert the monitor sends to a webhook target
	// HandleReceiveAlertWebhook handles the POST webhook for alertDelivery.
	HandleReceiveAlertWebhook(ctx echo.Context) error
}

// ReceiveAlertWebhookHandler returns the echo.HandlerFunc for the alertDelivery webhook.
// Mount this at the URL path advertised to webhook senders. Errors
// during parameter binding are returned via echo.NewHTTPError so echo's
// error-handling chain reports them as 400. Middlewares are applied in
// the order provided -- the last argument becomes the outermost wrapper.
func ReceiveAlertWebhookHandler(si WebhookReceiverInterface, middlewares ...echo.MiddlewareFunc) echo.HandlerFunc {
	h := echo.HandlerFunc(func(ctx echo.Context) error {
		return si.HandleReceiveAlertWebhook(ctx)
	})
	for _, mw := range middlewares {
		h = mw(h)
	}
	return h
}

